// Generated by vibelang from bench/probe.ts; the migrate flow writes it again with each batch.
// Code that runs inside the page. Playwright serializes each function with toString(), so every function
// here is self-contained: it uses only its argument and browser globals.
//
// Times are performance.now() milliseconds: relative to the page's navigation start, and comparable across
// pages once each page's performance.timeOrigin is added (the pages share one machine clock).
// The page's `POST /api/questions` requests that started at or after `since` (performance.now() milliseconds), in
// order. Only the chat outbox requests that path. A request is listed once its response has ended, so one still in
// flight isn't.
export function questionPosts(since) {
    const origin = performance.timeOrigin;
    return performance.getEntriesByType("resource")
        .filter((entry) => entry.startTime >= since && new URL(entry.name).pathname === "/api/questions")
        .map((entry) => ({ startAt: origin + entry.startTime, responseAt: origin + entry.responseStart, status: entry.responseStatus }));
}
// Installed before the page's own scripts on every navigation (BrowserContext.addInitScript).
export function installProbe(newestWord) {
    const COMPOSER = 'textarea[aria-label="Message Smithers"]';
    const probe = { usableAt: 0, newestAt: 0, messages: 0, lcp: 0, cmdKAt: 0, enterAt: 0, focusedAt: 0, exchanges: {} };
    window.__bench = probe;
    // Vite's dev server loads hundreds of modules, more than the default 250 resource entries, which would drop the
    // shape requests the load suite counts.
    performance.setResourceTimingBufferSize(10_000);
    new PerformanceObserver((list) => {
        for (const entry of list.getEntries())
            probe.lcp = entry.startTime;
    }).observe({ type: "largest-contentful-paint", buffered: true });
    // event.timeStamp is when the browser created the event, so input delay counts.
    addEventListener("keydown", (event) => {
        if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k")
            probe.cmdKAt = event.timeStamp;
        else if (event.key === "Enter" && !event.shiftKey)
            probe.enterAt = event.timeStamp;
    }, true);
    addEventListener("focusin", (event) => {
        if (event.target instanceof Element && event.target.matches(COMPOSER))
            probe.focusedAt = performance.now();
    }, true);
    const usable = () => document.querySelector(COMPOSER) !== null ||
        Array.from(document.querySelectorAll("button[aria-keyshortcuts]")).some((button) => button.textContent?.trim().startsWith("Chat"));
    // Mutation callbacks run right after React commits to the DOM, before the frame paints.
    const observer = new MutationObserver(() => {
        const now = performance.now();
        if (!probe.usableAt && usable())
            probe.usableAt = now;
        if (!probe.newestAt) {
            const conversation = document.querySelector('[aria-label="Conversation"]');
            if (conversation?.textContent?.includes(newestWord)) {
                probe.newestAt = now;
                probe.messages = conversation.querySelectorAll("article").length;
            }
        }
        if (probe.usableAt && probe.newestAt)
            observer.disconnect();
    });
    observer.observe(document, { childList: true, subtree: true, characterData: true });
}
// Records when the question containing `word` and each state of its answer reach this page's DOM. Both are found again
// after every change, never kept: the app remounts a message when its status changes (a queued question once Postgres
// has it, an answer when it settles), so an element found earlier may have left the DOM.
export function watchExchange(word) {
    const probe = window.__bench;
    const exchange = { questionAt: 0, questionText: "", firstTextAt: 0, completeAt: 0, answerText: "", samples: [] };
    probe.exchanges[word] = exchange;
    const conversation = document.querySelector('[aria-label="Conversation"]');
    if (conversation === null)
        throw new Error("the page has no Conversation region");
    const observer = new MutationObserver(() => {
        const now = performance.now();
        const question = Array.from(conversation.querySelectorAll('article[data-role="user"]')).find((element) => (element.textContent ?? "").includes(word));
        if (question === undefined)
            return;
        if (exchange.questionAt === 0) {
            exchange.questionAt = now;
            exchange.questionText = question.textContent ?? "";
        }
        // The answer is the article after its question; it shows a typing indicator until text arrives.
        const answer = question.nextElementSibling;
        const response = answer?.matches('article[data-role="assistant"]') ? answer.querySelector('[data-slot="message-response"]') : null;
        if (response === null || response === undefined)
            return;
        const text = response.textContent ?? "";
        if (text !== "" && text !== exchange.samples.at(-1)?.text)
            exchange.samples.push({ at: now, text });
        if (text !== "" && exchange.firstTextAt === 0)
            exchange.firstTextAt = now;
        if (response.getAttribute("data-streaming") === "false") {
            exchange.completeAt = now;
            exchange.answerText = text;
            observer.disconnect();
        }
    });
    observer.observe(conversation, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ["data-streaming"] });
}
